'use strict';
(() => {
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clone=v=>structuredClone(v), id=prefix=>prefix+'-'+crypto.randomUUID().replaceAll('-','').slice(0,16);
  const date=v=>{try{return new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Moscow'}).format(new Date(v));}catch{return '—';}};
  const money=v=>v===null||v===''||v===undefined?'Не указана':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(v);
  const base=new URL('../',location.href), asset=value=>{try{const url=new URL(value||'assets/ivory.webp',base);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return '';}};
  const nav=[['dashboard','Обзор'],['products','Товары'],['categories','Категории'],['media','Медиатека'],['divider','СОДЕРЖИМОЕ САЙТА'],['content','Тексты и кнопки'],['slides','Главный экран'],['sections','Разделы страницы'],['articles','Журнал'],['faq','Вопросы и ответы'],['reviews','Отзывы'],['documents','Документы'],['menus','Меню и ссылки'],['divider','НАСТРОЙКИ'],['appearance','Оформление и фото'],['settings','Контакты и SEO'],['history','История и копии'],['security','Доступ владельца']];
  let session=null,csrf='',data=null,working=null,dirty=false,section='dashboard',itemId=null,busy=false,setupToken='',notifyTimer,pickerTarget=null,pickerKind='image',pickerAppend=false,pickerCallback=null,contentGroup='hero',contentSearch='',productSearch='',productStatus='all',mediaSearch='',mediaTrash=false;
  const fragment=new URLSearchParams(location.hash.slice(1));
  if(fragment.has('setup')){setupToken=fragment.get('setup')||'';history.replaceState(null,'',location.pathname+location.search);}
  function notify(message,error=false){clearTimeout(notifyTimer);$('#notification').textContent=message;$('#notification').classList.toggle('error',error);$('#notification').hidden=false;notifyTimer=setTimeout(()=>$('#notification').hidden=true,6000);}
  async function api(action,body=null,method=body?'POST':'GET'){
    const headers={'Accept':'application/json'};if(method==='POST')headers['X-CSRF-Token']=csrf;
    const options={method,credentials:'same-origin',cache:'no-store',headers};
    if(body instanceof FormData)options.body=body;else if(body!==null){headers['Content-Type']='application/json';options.body=JSON.stringify(body);}
    const response=await fetch('api.php?action='+encodeURIComponent(action),options);let result;try{result=await response.json();}catch{throw new Error('Сервер не ответил. Обновите страницу или повторите позже.');}
    if(!response.ok){if(response.status===401&&action!=='login'){session=null;showAuth({initialized:true});}throw new Error(result.error||'Не удалось выполнить действие.');}
    if(result.csrf)csrf=result.csrf;return result;
  }
  function confirmAction(title,message,accept='Продолжить'){
    return new Promise(resolve=>{const dialog=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-accept').textContent=accept;let done=false;const finish=value=>{if(done)return;done=true;dialog.close();$('#confirm-accept').removeEventListener('click',yes);$('#confirm-cancel').removeEventListener('click',no);dialog.removeEventListener('cancel',cancel);resolve(value);};const yes=()=>finish(true),no=()=>finish(false),cancel=e=>{e.preventDefault();finish(false);};$('#confirm-accept').addEventListener('click',yes);$('#confirm-cancel').addEventListener('click',no);dialog.addEventListener('cancel',cancel);dialog.showModal();});
  }
  function showAuth(status){
    $('#admin-shell').hidden=true;$('#auth-screen').hidden=false;
    const setup=!status.initialized&&Boolean(setupToken)&&status.setupAvailable;
    $('#auth-card h1').textContent=setup?'Создайте доступ владельца':'Вход в ZAMELANO';
    $('#auth-description').textContent=setup?'Задайте собственный пароль. После создания доступа одноразовая ссылка больше не действует.':status.initialized?'Войдите, чтобы управлять товарами и содержимым обоих доменов.':'Панель подготовлена. Для первого входа нужна одноразовая ссылка владельца.';
    $('#auth-form').hidden=!status.initialized&&!setup;$('#owner-name').closest('label').hidden=!setup;$('#owner-name').hidden=!setup;$('#repeat-label').hidden=!setup;
    $('#auth-submit').textContent=setup?'Создать доступ и войти':'Войти';$('#auth-form [name=password]').autocomplete=setup?'new-password':'current-password';$('#auth-form [name=password]').minLength=setup?12:1;
    $('#auth-form').dataset.setup=String(setup);
  }
  async function refresh(){data=await api('data');working=clone(data.draft);dirty=false;updateTop();}
  async function start(){
    try{const status=await api('session');session=status.user;if(!session){showAuth(status);return;}await refresh();$('#auth-screen').hidden=true;$('#admin-shell').hidden=false;$('#owner-label').textContent=session.name||session.login;readRoute();renderNav();render();}
    catch(error){$('#auth-description').textContent=error.message;$('#auth-form').hidden=true;}
  }
  function renderNav(){let n=0;$('#main-nav').innerHTML=nav.map(([key,label])=>key==='divider'?`<span class="nav-divider">${label}</span>`:`<a href="#${key}"${key===section?' aria-current="page"':''}><span class="nav-number">${String(++n).padStart(2,'0')}</span>${esc(label)}</a>`).join('');}
  function updateTop(){if(!data)return;const changed=dirty||data.revision!==data.publishedRevision;$('#draft-status').textContent=dirty?'Есть несохранённые правки':changed?'Есть черновик':'Всё опубликовано';$('#draft-status').classList.toggle('is-dirty',changed);$('#publish').disabled=busy||(!changed);$('#page-title').textContent=nav.find(x=>x[0]===section)?.[1]||'Обзор';}
  function readRoute(){const [name,idValue]=location.hash.slice(1).split('/');section=nav.some(row=>row[0]===name&&name!=='divider')?name:'dashboard';itemId=idValue||null;}
  async function navigate(route){if(dirty&&!await confirmAction('Несохранённые правки','Перейти в другой раздел и отменить правки в этой форме? Сохранённый черновик останется.','Перейти'))return;dirty=false;working=clone(data.draft);history.replaceState(null,'','#'+route);readRoute();renderNav();render();$('#sidebar').classList.remove('is-open');syncSidebar();window.scrollTo({top:0});}
  function syncSidebar(){const mobile=window.matchMedia('(max-width:750px)').matches,open=$('#sidebar').classList.contains('is-open');$('#sidebar').inert=mobile&&!open;$('#sidebar-toggle').setAttribute('aria-expanded',String(mobile&&open));$('#sidebar-overlay').hidden=!(mobile&&open);}
  function markDirty(){dirty=true;updateTop();}
  function getPath(object,path){return path.split('.').reduce((value,key)=>value?.[key],object);}
  function setPath(object,path,value){const keys=path.split('.');let target=object;keys.forEach((key,index)=>{if(['__proto__','prototype','constructor'].includes(key))throw new Error('Недопустимое поле.');if(index===keys.length-1)target[key]=value;else target=target[key]??=(/^\d+$/.test(keys[index+1])?[]:{});});}
  function field(label,path,value,options={}){
    const type=options.type||'text',attr=`name="${esc(path)}"${options.required?' required':''}${options.readonly?' readonly':''}${options.min!==undefined?` min="${options.min}"`:''}${options.max!==undefined?` max="${options.max}"`:''}`;
    let input;
    if(type==='textarea'||type==='paragraphs'||type==='list'){const text=Array.isArray(value)?value.join(type==='paragraphs'?'\n\n':'\n'):(value??'');input=`<textarea ${attr} rows="${options.rows||3}" data-type="${type}">${esc(text)}</textarea>`;}
    else if(type==='select')input=`<select ${attr}>${(options.options||[]).map(row=>{const [v,l]=Array.isArray(row)?row:[row,row];return `<option value="${esc(v)}"${String(v)===String(value??'')?' selected':''}>${esc(l)}</option>`;}).join('')}</select>`;
    else input=`<input ${attr} type="${type==='nullable-number'?'number':type}" value="${esc(value??'')}"${type==='nullable-number'?' data-type="number" step="any"':''}>`;
    return `<label class="field${options.full?' full':''}"><span>${esc(label)}</span>${input}${options.help?`<small class="field-help">${esc(options.help)}</small>`:''}</label>`;
  }
  function check(label,path,value,help=''){return `<label class="check-field"><input type="checkbox" name="${esc(path)}"${value?' checked':''}><span>${esc(label)}${help?`<small class="field-help">${esc(help)}</small>`:''}</span></label>`;}
  function bilingual(label,path,value,options={}){return `<div class="field-block"><h3>${esc(label)}</h3><div class="bilingual">${field('Русский',path+'.ru',value?.ru,options)}${field('English',path+'.en',value?.en,options)}</div></div>`;}
  function rich(label,path,value){return `<div class="field-block"><h3>${esc(label)}</h3><div class="bilingual">${['ru','en'].map(lang=>{const raw=value?.[lang]||'',accent=(raw.match(/<em>(.*?)<\/em>/s)||[])[1]||'',text=raw.replace(/<br\s*\/?\s*>/gi,'\n').replace(/<[^>]*>/g,'');const key=path.replaceAll('.','-')+'-'+lang;return `<div>${field(lang==='ru'?'Русский':'English',path+'.'+lang,text,{type:'textarea',rows:3}) .replace('<textarea ','<textarea data-rich="'+key+'" ')}<label class="field"><span>Выделенная фраза</span><input data-accent="${key}" value="${esc(accent)}" placeholder="Необязательно"></label></div>`;}).join('')}</div></div>`;}
  function mediaField(label,path,value,kind='image'){return `<div class="media-field"><span>${esc(label)}</span><input type="hidden" name="${esc(path)}" value="${esc(value||'')}">${kind==='image'?`<img class="media-preview" src="${esc(asset(value))}" alt="Предпросмотр изображения">`:`<p class="muted small">${value?'Файл выбран':'Файл пока не выбран'}</p>`}<div class="row-actions"><button type="button" data-pick="${esc(path)}" data-kind="${kind}">Выбрать ${kind==='image'?'фото':'файл'}</button><button type="button" data-clear-media="${esc(path)}">Убрать</button></div></div>`;}
  function saveBar(label='Сохранить черновик'){return `<div class="save-bar"><span>Изменения появятся на обоих доменах после публикации.</span><button class="primary" type="submit">${label}</button></div>`;}
  function intro(text,buttons=''){return `<div class="page-intro"><p>${text}</p>${buttons?`<div class="page-actions">${buttons}</div>`:''}</div>`;}
  function collect(){const form=$('#editor');if(!form)return;for(const input of $$('[name]',form)){let value=input.type==='checkbox'?input.checked:input.value;const type=input.dataset.type;if(type==='number')value=value===''?null:Number(value);else if(type==='list')value=value.split(/[\n,]/).map(s=>s.trim()).filter(Boolean);else if(type==='paragraphs')value=value.split(/\n\s*\n/).map(s=>s.trim()).filter(Boolean);if(input.dataset.rich){let text=esc(input.value);const accent=$(`[data-accent="${input.dataset.rich}"]`,form)?.value||'';if(accent)text=text.replace(esc(accent),'<em>'+esc(accent)+'</em>');value=text.replace(/\n/g,'<br>');}setPath(working,input.name,value);}}
  async function save(label=nav.find(x=>x[0]===section)?.[1]||'Содержимое'){
    if(busy)return;collect();busy=true;updateTop();try{const result=await api('save',{revision:data.revision,payload:working,label});await refresh();render();notify('Черновик сохранён. Можно проверить его в предпросмотре.');return result;}finally{busy=false;updateTop();}
  }
  function dashboard(){const p=working.catalog.products,visible=p.filter(p=>p.status==='published'),drafts=p.filter(p=>p.status==='draft'),trash=p.filter(p=>p.status==='trash');return intro('Управляйте витриной ZAMELANO из одного места. Одна публикация обновляет оба домена.')+`<div class="stats-grid">${[[visible.length,'Товаров в витрине'],[drafts.length,'Черновиков товаров'],[working.documents.documents.length,'Документов'],[data.revision===data.publishedRevision?'Готово':'Черновик','Состояние публикации']].map(([n,title])=>`<div class="stat"><p>${title}</p><strong>${n}</strong><p>${title==='Состояние публикации'?'Последняя публикация: '+date(data.publishedAt):title==='Товаров в витрине'?`${p.filter(x=>x.concept&&x.status!=='trash').length} концепций`:'Редактирование доступно'}</p></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><p class="eyebrow">НАЧНИТЕ С ГЛАВНОГО</p><h2>Ваш бутик сегодня</h2><p>Создавайте товары, меняйте фотографии и тексты. Сначала сохраните черновик, затем проверьте сайт и опубликуйте изменения.</p><div class="quick-links"><a href="#products/new">Добавить товар</a><a href="#slides">Изменить главный экран</a><a href="#appearance">Обновить фотографии</a><a href="#documents">Открыть документы</a></div><p class="tone-note">Заявки по-прежнему готовятся для отправки в Telegram. Админка управляет содержимым сайта; онлайн-оплата и приём заказов в базу не подключены.</p></section><section class="panel"><p class="eyebrow">ИСТОРИЯ РАБОТЫ</p><h2>Последние действия</h2>${data.audit.slice(0,6).map(row=>`<div class="activity-row">${esc(row.action)}${row.detail?`<span class="muted"> · ${esc(row.detail)}</span>`:''}<time>${date(row.at)}</time></div>`).join('')||'<p>Здесь появятся сохранения и публикации.</p>'}</section></div>`;}
  function productTable(){const products=working.catalog.products.filter(p=>(productStatus==='all'?p.status!=='trash':p.status===productStatus)&&(!productSearch||`${p.name.ru} ${p.name.en} ${p.sku}`.toLowerCase().includes(productSearch.toLowerCase())));return products.length?`<div class="table-wrap"><table><thead><tr><th>Товар</th><th>Цена</th><th>Остаток</th><th>Статус</th><th></th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="product-cell"><img src="${esc(asset(p.image))}" alt=""><div><button class="product-name-button" data-product-edit="${p.id}">${esc(p.name.ru)}</button><small>${esc(p.sku||'Без артикула')}${p.concept?' · концепция':''}</small></div></div></td><td>${money(p.price)}</td><td>${p.stock===null?'Не указан':p.stock}</td><td><span class="badge ${p.status}">${({published:'В витрине',draft:'Черновик',trash:'Корзина'})[p.status]}</span></td><td><div class="row-actions">${p.status==='trash'?`<button data-product-restore="${p.id}">Восстановить</button>`:`<button data-product-edit="${p.id}">Редактировать</button><button data-product-copy="${p.id}">Копия</button><button data-product-trash="${p.id}" class="delete-inline">В корзину</button>`}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="panel empty-state"><h2>Товаров пока нет</h2><p>Добавьте первый товар или измените фильтр.</p></div>';}
  function products(){return intro('Добавляйте и редактируйте товары, цены, размеры, цвета и остатки. Удаление переносит товар в корзину.',`<button class="primary" data-new-product>Добавить товар</button>`)+`<div class="toolbar"><input type="search" id="product-search" value="${esc(productSearch)}" placeholder="Название или артикул" aria-label="Поиск товара"><select id="product-status" aria-label="Статус товара">${[['all','Все товары'],['published','В витрине'],['draft','Черновики'],['trash','Корзина']].map(([v,l])=>`<option value="${v}"${v===productStatus?' selected':''}>${l}</option>`).join('')}</select></div><div id="product-table">${productTable()}</div>`;}
  function productEditor(){const index=working.catalog.products.findIndex(p=>p.id===itemId);if(index<0)return '<div class="panel"><p>Товар не найден.</p><a href="#products">Вернуться в каталог</a></div>';const p=working.catalog.products[index],path='catalog.products.'+index;return intro('Сохраните карточку как черновик. Публикация на обоих доменах выполняется общей кнопкой вверху.',`<a class="button secondary" href="#products">Все товары</a>`)+`<form id="editor" data-label="Товар: ${esc(p.name.ru)}"><div class="editor-grid"><div><section class="panel"><h2>Карточка товара</h2>${bilingual('Название',path+'.name',p.name,{required:true})}${bilingual('Описание, состав и уход',path+'.description',p.description,{type:'textarea',rows:7})}<div class="form-grid">${field('Артикул',path+'.sku',p.sku)}${field('Категория',path+'.category',p.category,{type:'select',options:[['','Без категории'],...working.content.categories.map(c=>[c.id,c.title.ru])]})}${field('Коллекция',path+'.collection',p.collection)}${field('Палитра карточки',path+'.palette',p.palette,{type:'select',options:[['ivory','Молочная'],['black','Тёмная'],['peach','Персиковая']]})}</div></section><section class="panel"><h2>Размеры и цвета</h2><div class="form-grid">${field('Размеры',path+'.sizes',p.sizes,{type:'list',help:'Каждый размер с новой строки или через запятую.'})}${field('Цвета',path+'.colors',p.colors,{type:'list',help:'Каждый цвет с новой строки или через запятую.'})}</div></section><section class="panel"><h2>Фотографии галереи</h2><textarea name="${path}.images" data-type="list" hidden>${esc((p.images||[]).join('\n'))}</textarea><div class="media-grid">${(p.images||[]).map((src,gi)=>`<div class="media-card"><img src="${esc(asset(src))}" alt="Фото ${gi+1}"><p>Фото ${gi+1}</p><div class="row-actions"><button type="button" data-gallery-move="${index}:${gi}:-1">Выше</button><button type="button" data-gallery-move="${index}:${gi}:1">Ниже</button><button type="button" data-gallery-remove="${index}:${gi}">Убрать</button></div></div>`).join('')}</div><button class="secondary" type="button" data-pick="${path}.images" data-kind="image" data-append>Добавить фото из медиатеки</button></section></div><div><section class="panel"><h2>Цена и наличие</h2>${field('Цена, ₽',path+'.price',p.price,{type:'nullable-number',min:0})}${field('Старая цена, ₽',path+'.oldPrice',p.oldPrice,{type:'nullable-number',min:0,help:'Показывается зачёркнутой, если больше текущей.'})}${field('Остаток, шт.',path+'.stock',p.stock,{type:'nullable-number',min:0,help:'Пусто — наличие уточняется. 0 — нет в наличии.'})}${field('Публикация карточки',path+'.status',p.status,{type:'select',options:[['draft','Черновик'],['published','Показывать в витрине']]})}${check('Это визуальная концепция',path+'.concept',p.concept,'Для реальных товаров снимите отметку.')}</section><section class="panel"><h2>Главная фотография</h2>${mediaField('Фото в каталоге',path+'.image',p.image)}</section></div></div>${saveBar()}</form>`;}
  const contentLabels={announcement:'Сообщение над шапкой',heroEyebrow:'Подпись главного экрана',explore:'Кнопка открытия каталога',discoverBrand:'Ссылка о бренде',heroFoot:'Подпись под главным экраном',brandEyebrow:'Подпись раздела о бренде',brandTitle:'Заголовок раздела о бренде',brandText1:'Первый абзац о бренде',brandText2:'Второй абзац о бренде',catalogTitle:'Заголовок каталога',catalogNote:'Пояснение к каталогу',wholesaleTitle:'Заголовок оптового раздела',wholesaleText:'Текст оптового раздела',wholesaleButton:'Кнопка для партнёров',footerTagline:'Подпись под логотипом',cookieTitle:'Заголовок cookie-попапа',cookieText:'Текст cookie-попапа',understood:'Кнопка закрытия cookie-попапа'};
  function textGroup(key){if(/^(announcement|hero|explore|discover|value)/.test(key))return 'hero';if(/^(brand|askBrand)/.test(key))return 'brand';if(/^(catalog|filter|all|size|color|collection|price|reset|sort|ivory|black|peach|search|model|stock|detail|product|card|outOfStock|inStock)/.test(key))return 'catalog';if(/^(journal|article|guide|news|reviews)/.test(key))return 'journal';if(/^(wholesale)/.test(key))return 'wholesale';if(/^(delivery|payment|service|gifts|sizeHelp|openSize|askDetails|faq|askTelegram)/.test(key))return 'service';return 'interface';}
  function textFields(){const c=working.content;const excluded=/^(heroTitle\d?|heroDescription\d?|faq\d+|faq\d+Answer|articleFit|articleCare|articleNews|ivoryConcept|blackConcept|peachConcept|individual|legalAddress.*|taxId|registrationId|account|correspondent|bic|bank.*|entrepreneur.*|taxSystem|taxName|privacyText|offerText|returnText|legalPending|guide|details|news)$/;const source=contentGroup==='legal'?(c.legalUI?.ru||{}):c.translations.ru;const keys=Object.keys(source).filter(key=>!excluded.test(key)&&(contentGroup==='all'||contentGroup==='legal'||textGroup(key)===contentGroup)&&(!contentSearch||`${contentLabels[key]||''} ${source[key]}`.toLowerCase().includes(contentSearch.toLowerCase())));return keys.map(key=>{const value={ru:source[key],en:contentGroup==='legal'?c.legalUI.en[key]:c.translations.en[key]};const label=contentLabels[key]||String(source[key]).replace(/<[^>]*>/g,' ').slice(0,82);if(/^(brandTitle|wholesaleTitle)$/.test(key))return rich(label,'content.translations.'+key,value).replaceAll('name="content.translations.'+key+'.ru"','name="content.translations.ru.'+key+'"').replaceAll('name="content.translations.'+key+'.en"','name="content.translations.en.'+key+'"');return `<div class="field-block"><h3>${esc(label||'Текст интерфейса')}</h3><div class="bilingual">${field('Русский',`content.${contentGroup==='legal'?'legalUI':'translations'}.ru.${key}`,value.ru,{type:'textarea',rows:value.ru.length>150?4:2})}${field('English',`content.${contentGroup==='legal'?'legalUI':'translations'}.en.${key}`,value.en,{type:'textarea',rows:(value.en||'').length>150?4:2})}</div></div>`;}).join('')||'<p class="muted">Ничего не найдено.</p>';}
  function content(){return intro('Тексты страниц и кнопок на русском и английском. Главный экран, вопросы, статьи и документы редактируются в своих разделах.')+`<div class="toolbar"><select id="content-group" aria-label="Группа текстов">${[['hero','Главная и преимущества'],['brand','О бренде'],['catalog','Каталог'],['journal','Журнал и отзывы'],['service','Доставка и подсказки'],['wholesale','Оптовым партнёрам'],['interface','Кнопки, формы и подписи'],['legal','Документы и cookie'],['all','Все тексты']].map(([v,l])=>`<option value="${v}"${v===contentGroup?' selected':''}>${l}</option>`).join('')}</select><input id="content-search" type="search" placeholder="Найти текст" value="${esc(contentSearch)}" aria-label="Поиск текста"></div><form id="editor" data-label="Тексты сайта"><section class="panel" id="content-fields">${textFields()}</section>${saveBar()}</form>`;}
  function collectionHeader(title,key,index){return `<div class="collection-card-header"><h3>${esc(title)}</h3><div class="row-actions"><button type="button" data-move="${key}:${index}:-1">Выше</button><button type="button" data-move="${key}:${index}:1">Ниже</button><button type="button" data-remove="${key}:${index}" class="delete-inline">Убрать</button></div></div>`;}
  function collectionView(key){const rows=working.content[key]||[];let body='';
    if(key==='slides')body=rows.map((r,i)=>`<section class="collection-card">${collectionHeader('Слайд '+(i+1),key,i)}${rich('Заголовок',`content.slides.${i}.title`,r.title)}${bilingual('Описание',`content.slides.${i}.description`,r.description,{type:'textarea'})}</section>`).join('');
    if(key==='faq')body=rows.map((r,i)=>`<section class="collection-card">${collectionHeader('Вопрос '+(i+1),key,i)}${bilingual('Вопрос',`content.faq.${i}.question`,r.question)}${bilingual('Ответ',`content.faq.${i}.answer`,r.answer,{type:'textarea',rows:4})}</section>`).join('');
    if(key==='categories')body=rows.map((r,i)=>`<section class="collection-card">${collectionHeader(r.title.ru||'Новая категория',key,i)}${bilingual('Название категории',`content.categories.${i}.title`,r.title)}${check('Показывать категорию',`content.categories.${i}.visible`,r.visible!==false)}</section>`).join('');
    if(key==='reviews')body=rows.map((r,i)=>`<section class="collection-card">${collectionHeader(r.name||'Новый отзыв',key,i)}${field('Имя автора',`content.reviews.${i}.name`,r.name)}${bilingual('Текст отзыва',`content.reviews.${i}.text`,r.text,{type:'textarea',rows:4})}${mediaField('Фотография автора',`content.reviews.${i}.image`,r.image)}${check('Показывать отзыв',`content.reviews.${i}.visible`,r.visible!==false)}</section>`).join('');
    if(key==='sections')body=rows.map((r,i)=>`<section class="collection-card">${collectionHeader(r.title||'Новый раздел',key,i)}${check('Показывать раздел',`content.sections.${i}.visible`,r.visible!==false)}${r.type==='text'?`${field('Название в админке',`content.sections.${i}.title`,r.title)}${bilingual('Заголовок',`content.sections.${i}.heading`,r.heading)}${bilingual('Текст',`content.sections.${i}.text`,r.text,{type:'textarea',rows:5})}${mediaField('Изображение',`content.sections.${i}.image`,r.image)}${bilingual('Подпись кнопки',`content.sections.${i}.button`,r.button)}${field('Ссылка кнопки',`content.sections.${i}.href`,r.href,{help:'Например: #catalog или https://example.com/'})}`:`<p class="section-label">Содержимое этого раздела редактируется в разделе «${esc(({hero:'Главный экран',values:'Тексты и кнопки',catalog:'Товары',brand:'Тексты и кнопки',journal:'Журнал',delivery:'Тексты и кнопки',faq:'Вопросы и ответы',reviews:'Отзывы',wholesale:'Тексты и кнопки'})[r.id]||'Тексты и кнопки')}».</p>`}</section>`).join('');
    const titles={slides:'Добавить слайд',faq:'Добавить вопрос',categories:'Добавить категорию',reviews:'Добавить отзыв',sections:'Добавить текстовый раздел'};
    return intro(key==='sections'?'Меняйте порядок блоков, скрывайте разделы и добавляйте собственные блоки с текстом, изображением и кнопкой.':key==='reviews'?'Добавляйте согласованные отзывы вручную. Публикация отзывов на сайте управляется отдельно от заявок.':'Добавляйте, редактируйте и меняйте порядок элементов.')+`<form id="editor" data-label="${esc(nav.find(r=>r[0]===key)?.[1])}">${body||'<section class="panel empty-state"><p>Элементов пока нет.</p></section>'}<div class="collection-actions"><button class="secondary" type="button" data-add="${key}">${titles[key]}</button></div>${saveBar()}</form>`;
  }
  function articles(){return intro('Статьи журнала с фотографиями и текстами на двух языках.',`<button class="primary" data-new-article>Добавить статью</button>`)+`<div class="table-wrap"><table><thead><tr><th>Статья</th><th>Статус</th><th></th></tr></thead><tbody>${working.content.articles.map(a=>`<tr><td>${esc(a.title.ru)}</td><td><span class="badge ${a.status}">${a.status==='published'?'Опубликована':a.status==='trash'?'Корзина':'Черновик'}</span></td><td><div class="row-actions"><button data-article-edit="${a.id}">Редактировать</button><button data-article-state="${a.id}">${a.status==='trash'?'Восстановить':'В корзину'}</button></div></td></tr>`).join('')}</tbody></table></div>`;}
  function articleEditor(){const index=working.content.articles.findIndex(a=>a.id===itemId),a=working.content.articles[index];if(!a)return '<div class="panel">Статья не найдена.</div>';const path='content.articles.'+index;return intro('Одна статья — две языковые версии.',`<a class="button secondary" href="#articles">Все статьи</a>`)+`<form id="editor" data-label="Статья: ${esc(a.title.ru)}"><section class="panel">${bilingual('Заголовок',path+'.title',a.title)}${bilingual('Рубрика',path+'.tag',a.tag)}${bilingual('Текст статьи',path+'.paragraphs',a.paragraphs,{type:'paragraphs',rows:13})}${mediaField('Обложка',path+'.image',a.image)}${field('Статус',path+'.status',a.status,{type:'select',options:[['draft','Черновик'],['published','Показывать в журнале'],['trash','Корзина']]})}</section>${saveBar()}</form>`;}
  function documents(){return intro('Полные тексты, таблицы и файлы юридических документов. Изменения сначала сохраняются в черновик.',`<button class="primary" data-new-document>Добавить документ</button>`)+`<div class="panel">${working.documents.documents.map(doc=>`<div class="history-row"><div><p>${esc(doc.label.ru)}</p><small>${esc(doc.title)}</small></div><button data-document-edit="${doc.id}">Редактировать</button></div>`).join('')}</div><form id="editor" data-label="Версии документов"><section class="panel"><h2>Редакция комплекта</h2><div class="form-grid">${field('Версия политики', 'documents.policyVersion',working.documents.policyVersion)}${field('Дата комплекта','documents.packetDate',working.documents.packetDate,{type:'date'})}${field('Свой адрес сайта для документов','links.siteUrl',working.links.siteUrl,{full:true,help:'Пусто — адрес текущего домена подставляется автоматически.'})}</div></section>${saveBar()}</form>`;}
  function documentEditor(){const index=working.documents.documents.findIndex(d=>d.id===itemId),doc=working.documents.documents[index];if(!doc)return '<div class="panel">Документ не найден.</div>';const path='documents.documents.'+index;return intro('Редактируйте текст по абзацам. При загрузке Word можно перенести его текст в черновик.',`<a class="button secondary" href="#documents">Все документы</a>`)+`<form id="editor" data-label="Документ: ${esc(doc.label.ru)}"><section class="panel">${bilingual('Название в списке',path+'.label',doc.label)}${field('Полный заголовок',path+'.title',doc.title,{type:'textarea',rows:2})}${check('Показывать в списке документов',path+'.visible',doc.visible!==false)}${mediaField('Файл для скачивания (PDF или DOCX)','links.files.'+doc.id,working.links.files[doc.id],'document')}<button type="button" class="secondary" data-import-word="${index}">Перенести текст из Word</button><p class="small muted">Текст на сайте и прикреплённый файл сохраняются отдельно. Изменения можно проверить перед публикацией.</p></section><section class="panel"><h2>Текст документа</h2>${doc.blocks.map((b,i)=>i<2?'':`<div class="doc-block"><div class="doc-block-header">${field('Тип блока',`${path}.blocks.${i}.type`,b.type,{type:'select',options:[['paragraph','Абзац'],['heading','Заголовок раздела'],['subheading','Подзаголовок'],['list-item','Элемент списка'],['table','Таблица']]})}<button type="button" data-remove-block="${index}:${i}">Убрать блок</button></div>${b.type==='table'?b.rows.map((row,ri)=>`<div class="doc-table-row">${row.map((cell,ci)=>field(ci===0?'Поле':'Значение',`${path}.blocks.${i}.rows.${ri}.${ci}`,cell,{type:'textarea',rows:2})).join('')}<button type="button" data-remove-table-row="${index}:${i}:${ri}">Убрать</button></div>`).join('')+`<button type="button" class="secondary" data-add-table-row="${index}:${i}">Добавить строку</button>`:field('Текст',`${path}.blocks.${i}.text`,b.text,{type:'textarea',rows:b.text.length>300?5:3})}</div>`).join('')}<div class="collection-actions"><button type="button" class="secondary" data-add-block="${index}:paragraph">Добавить абзац</button><button type="button" class="secondary" data-add-block="${index}:heading">Добавить заголовок</button><button type="button" class="secondary" data-add-block="${index}:table">Добавить таблицу</button></div></section>${saveBar()}</form>`;}
  function menuRow(path,row,removeValue){return `<div class="menu-link-row">${field('Русский',path+'.label.ru',row.label.ru)}${field('English',path+'.label.en',row.label.en)}${field('Адрес',path+'.href',row.href)}<button type="button" data-remove-menu="${removeValue}" class="delete-inline">Убрать</button></div>`;}
  function menus(){const m=working.content.menus;return intro('Редактируйте навигацию шапки, мобильного меню и подвала. Ссылка на документ открывает окно чтения.')+`<form id="editor" data-label="Меню и ссылки"><section class="panel"><h2>Кнопки главного экрана</h2><div class="form-grid">${field('Ссылка «Открыть каталог»','content.settings.actionLinks.heroCatalog',working.content.settings.actionLinks.heroCatalog)}${field('Ссылка «О бренде»','content.settings.actionLinks.heroBrand',working.content.settings.actionLinks.heroBrand)}</div></section><section class="panel"><h2>Шапка и мобильное меню</h2>${m.header.map((r,i)=>menuRow('content.menus.header.'+i,r,'header:'+i)).join('')}<button class="secondary" type="button" data-add-menu="header">Добавить ссылку</button></section>${m.footer.map((group,gi)=>`<section class="panel">${bilingual('Заголовок группы',`content.menus.footer.${gi}.title`,group.title)}${group.items.map((r,i)=>menuRow(`content.menus.footer.${gi}.items.${i}`,r,`footer:${gi}:${i}`)).join('')}<div class="collection-actions"><button class="secondary" type="button" data-add-menu="footer:${gi}">Добавить ссылку</button><button class="danger" type="button" data-remove-footer-group="${gi}">Убрать группу</button></div></section>`).join('')}<button class="secondary" type="button" data-add-footer-group>Добавить группу в подвал</button>${saveBar()}</form>`;}
  function appearance(){const c=working.content,s=c.settings,colors={paper:'Фон сайта',peach:'Персиковый акцент',peachLight:'Светлый акцент',ink:'Основной текст',muted:'Вторичный текст',gold:'Золотой акцент',line:'Линии и границы'},images={hero:'Главное изображение',brand:'Раздел о бренде',footerLogo:'Логотип в подвале'};return intro('Оформление сайта, фирменная графика и фотографии. Текущие пропорции изображений сохраняются.')+`<form id="editor" data-label="Оформление и фотографии"><section class="panel"><h2>Палитра</h2><div class="color-grid">${Object.entries(colors).map(([k,l])=>field(l,'content.settings.theme.'+k,s.theme[k],{type:'color'})).join('')}</div></section><section class="panel"><h2>Типографика и форма</h2><div class="form-grid">${field('Шрифт заголовков','content.settings.theme.serif',s.theme.serif,{type:'select',options:['Georgia','Times New Roman','Palatino Linotype','Arial','Helvetica','Verdana','Trebuchet MS']})}${field('Шрифт текста','content.settings.theme.sans',s.theme.sans,{type:'select',options:['Arial','Helvetica','Verdana','Trebuchet MS','Georgia']})}${field('Скругления фотографий, px','content.settings.theme.radius',s.theme.radius,{type:'nullable-number',min:0,max:80,help:'Пусто — сохранить исходные скругления.'})}</div></section><section class="panel"><h2>Шапка и подвал</h2>${check('Показывать шапку','content.settings.showHeader',s.showHeader!==false)}${check('Показывать подвал','content.settings.showFooter',s.showFooter!==false)}</section><section class="panel"><h2>Фирменная графика</h2><div class="image-settings-grid">${mediaField('Новый логотип в шапке','content.settings.headerLogo',s.headerLogo)}${mediaField('Иконка вкладки','content.settings.favicon',s.favicon)}</div><p class="small muted">Если новый логотип не выбран, используется исходный фирменный знак без розового фона.</p></section><div class="image-settings-grid">${Object.entries(images).map(([k,label])=>`<section class="panel"><h2>${label}</h2>${mediaField('Файл',`content.images.${k}.src`,c.images[k].src)}${bilingual('Описание изображения',`content.images.${k}.alt`,c.images[k].alt)}</section>`).join('')}</div>${saveBar()}</form>`;}
  function settings(){const s=working.content.settings;return intro('Контактные данные, описание сайта и параметры каталога. Адреса обоих доменов продолжают работать.')+`<form id="editor" data-label="Контакты и настройки"><section class="panel"><h2>Основное</h2>${field('Название бренда','content.settings.name',s.name)}${bilingual('Подпись внизу сайта','content.settings.copyright',s.copyright)}${field('Режим каталога','content.settings.catalogMode',s.catalogMode,{type:'select',options:[['concept','Концепция витрины'],['live','Реальные товары']]})}</section><section class="panel"><h2>Контакты</h2><div class="form-grid">${field('Телефон','content.settings.contacts.phone',s.contacts.phone)}${field('Telegram','content.settings.contacts.telegram',s.contacts.telegram,{help:'Полный адрес, например https://t.me/Zamelano'})}${field('Instagram','content.settings.contacts.instagram',s.contacts.instagram)}${field('Электронная почта','content.settings.contacts.emails',s.contacts.emails,{type:'list',help:'Каждый адрес с новой строки.'})}</div></section><section class="panel"><h2>Поисковое описание</h2>${bilingual('Заголовок вкладки и поиска','content.settings.title',s.title)}${bilingual('Описание сайта','content.settings.description',s.description,{type:'textarea',rows:4})}${field('Версия cookie-уведомления','content.settings.cookieNoticeVersion',s.cookieNoticeVersion,{help:'Измените значение, чтобы снова показать уведомление посетителям.'})}${check('Разрешить индексацию боевого сайта','content.settings.indexing',s.indexing,'Демонстрация GitHub Pages по-прежнему закрыта от индексации.')}</section>${saveBar()}</form>`;}
  function mediaCards(files,picker=false){return files.length?files.map(m=>`<article class="media-card">${m.kind==='image'?`<img src="${esc(asset(m.url))}" alt="${esc(m.name)}" loading="lazy">`:`<div class="media-file-icon">${esc((m.ext||'FILE').toUpperCase())}</div>`}<p title="${esc(m.name)}">${esc(m.name)}</p><small>${m.width?`${m.width} × ${m.height} · `:''}${(m.size/1024).toFixed(0)} КБ${m.base?' · исходный файл':''}</small>${picker?`<button type="button" data-choose-media="${esc(m.id)}">Выбрать</button>`:`<a href="${esc(asset(m.url))}" class="media-open-link" target="_blank" rel="noopener">Открыть</a>${m.base?'':`<button type="button" data-media-state="${m.id}">${m.trash?'Восстановить':'В корзину'}</button>`}`}</article>`).join(''):'<div class="empty-state"><p>Файлов пока нет.</p></div>';}
  function media(){const files=data.media.filter(m=>Boolean(m.trash)===mediaTrash&&(!mediaSearch||m.name.toLowerCase().includes(mediaSearch.toLowerCase())));return intro('Фотографии и файлы документов. Загруженные изображения можно выбрать для любого раздела сайта.')+`<div class="media-toolbar"><input id="library-search" type="search" placeholder="Поиск файла" value="${esc(mediaSearch)}" aria-label="Поиск в медиатеке"><button class="secondary" type="button" id="media-trash-toggle">${mediaTrash?'Все файлы':'Корзина'}</button><label class="button primary upload-button">Загрузить<input type="file" id="library-upload" multiple accept="image/jpeg,image/png,image/webp,application/pdf,.docx" hidden></label></div><p class="small muted">JPG, PNG, WebP, PDF или DOCX. До 10 МБ на файл. Изображения — до 16 мегапикселей.</p><div class="media-grid" id="library-grid">${mediaCards(files)}</div>`;}
  function historyView(){return intro('Сохраняются последние 50 версий. Восстановление создаёт черновик — посетители увидят его только после публикации.',`<a class="button secondary" href="api.php?action=backup">Скачать копию содержимого</a><button class="secondary" data-import-backup>Восстановить из файла</button>`)+`<section class="panel"><h2>Версии содержимого</h2>${data.history.map(row=>`<div class="history-row"><div><p>${esc(row.label)}</p><small>${date(row.at)} · ${esc(row.user)} · версия ${row.revision}</small></div><button data-restore-version="${row.id}">Восстановить в черновик</button></div>`).join('')||'<p class="muted">История появится после первого сохранения.</p>'}</section><section class="panel"><h2>Журнал действий</h2>${data.audit.slice(0,70).map(row=>`<div class="activity-row">${esc(row.action)}${row.detail?` · ${esc(row.detail)}`:''}<time>${date(row.at)} · ${esc(row.user)}</time></div>`).join('')}</section>`;}
  function security(){return intro('Доступ владельца защищён паролем. После изменения пароля другие открытые сессии перестанут действовать.')+`<form id="password-form" class="panel"><h2>Изменить пароль</h2><p class="muted">Логин: ${esc(session.login)}</p><div class="form-grid">${field('Текущий пароль','currentPassword','',{type:'password',required:true,full:true})}${field('Новый пароль','newPassword','',{type:'password',required:true})}${field('Повторите новый пароль','repeatPassword','',{type:'password',required:true})}</div><p class="small muted">От 12 до 128 символов. Пароль не добавляется в файлы сайта и резервные копии содержимого.</p><button class="primary" type="submit">Изменить пароль</button></form>`;}
  function render(){if(!data)return;updateTop();let html;switch(section){case'dashboard':html=dashboard();break;case'products':html=itemId?productEditor():products();break;case'content':html=content();break;case'slides':case'faq':case'categories':case'reviews':case'sections':html=collectionView(section);break;case'articles':html=itemId?articleEditor():articles();break;case'documents':html=itemId?documentEditor():documents();break;case'menus':html=menus();break;case'appearance':html=appearance();break;case'settings':html=settings();break;case'media':html=media();break;case'history':html=historyView();break;case'security':html=security();break;default:html=dashboard();}$('#workspace').innerHTML=html;}
  function openPicker(target,kind='image',append=false,callback=null){pickerTarget=target;pickerKind=kind;pickerAppend=append;pickerCallback=callback;$('#media-search').value='';renderPicker();$('#media-dialog').showModal();}
  function renderPicker(){const query=$('#media-search').value.toLowerCase();const files=data.media.filter(m=>!m.trash&&(pickerKind==='any'||(pickerKind==='word'?m.ext==='docx':m.kind===pickerKind))&&(!query||m.name.toLowerCase().includes(query)));$('#media-picker-grid').innerHTML=mediaCards(files,true);$('#media-picker-upload').accept=pickerKind==='image'?'image/jpeg,image/png,image/webp':pickerKind==='word'?'.docx':'application/pdf,.docx';}
  async function uploadFiles(files){for(const file of files){notify('Загружаем '+file.name+'…');const form=new FormData();form.append('file',file);const result=await api('upload',form);data.media.push(result.file);}notify('Файлы загружены.');}
  function addCollection(key){collect();const pair={ru:'',en:''};const defaults={slides:{id:id('slide'),title:clone(pair),description:clone(pair)},faq:{id:id('faq'),question:clone(pair),answer:clone(pair)},categories:{id:id('category'),title:clone(pair),visible:true},reviews:{id:id('review'),name:'',text:clone(pair),image:null,visible:true},sections:{id:id('section'),type:'text',title:'Новый раздел',visible:true,heading:clone(pair),text:clone(pair),image:null,button:clone(pair),href:null}};working.content[key].push(defaults[key]);markDirty();render();}
  function newProduct(){working=clone(data.draft);const p={id:id('product'),name:{ru:'Новый товар',en:''},description:{ru:'',en:''},image:'assets/ivory.webp',images:[],sku:'',category:working.content.categories[0]?.id||'',palette:'ivory',collection:'',price:null,oldPrice:null,stock:null,sizes:[],colors:[],status:'draft',concept:false};working.catalog.products.push(p);itemId=p.id;section='products';history.replaceState(null,'','#products/'+p.id);markDirty();renderNav();render();}
  function newArticle(){working=clone(data.draft);const a={id:id('article'),title:{ru:'Новая статья',en:''},paragraphs:{ru:[],en:[]},tag:{ru:'Журнал',en:'Journal'},image:null,status:'draft'};working.content.articles.push(a);itemId=a.id;section='articles';history.replaceState(null,'','#articles/'+a.id);markDirty();render();}
  function newDocument(){working=clone(data.draft);const doc={id:id('document'),label:{ru:'Новый документ',en:''},title:'Новый документ',language:'ru',blocks:[{type:'paragraph',text:'Новый документ'},{type:'paragraph',text:''},{type:'paragraph',text:''}]};working.documents.documents.push(doc);working.links.files[doc.id]=null;itemId=doc.id;section='documents';history.replaceState(null,'','#documents/'+doc.id);markDirty();render();}
  document.addEventListener('click',async event=>{const target=event.target.closest('button,a');if(!target)return;try{
    if(target.matches('a[href^="#"]')){event.preventDefault();const route=target.getAttribute('href').slice(1);if(route==='products/new'){if(!dirty||await confirmAction('Новая карточка','Отменить несохранённые правки и создать товар?','Создать'))newProduct();}else await navigate(route);return;}
    if(target.id==='sidebar-toggle'){$('#sidebar').classList.toggle('is-open');syncSidebar();return;}if(target.id==='sidebar-overlay'){$('#sidebar').classList.remove('is-open');syncSidebar();return;}
    if(target.id==='logout'){if(dirty&&!await confirmAction('Выйти из панели','Несохранённые правки в форме будут отменены.','Выйти'))return;await api('logout',{});dirty=false;data=null;session=null;await start();return;}
    if(target.id==='publish'){if(dirty){notify('Сначала сохраните правки в форме.',true);return;}if(!await confirmAction('Опубликовать изменения?','Текущий черновик станет виден посетителям zamelano.com и zamelano.ru. Предыдущая версия сохранится в истории.','Опубликовать'))return;busy=true;updateTop();await api('publish',{revision:data.revision});await refresh();render();notify('Сайт обновлён на обоих доменах.');busy=false;updateTop();return;}
    if(target.hasAttribute('data-new-product')){newProduct();return;}if(target.hasAttribute('data-new-article')){newArticle();return;}if(target.hasAttribute('data-new-document')){newDocument();return;}
    if(target.dataset.productEdit){await navigate('products/'+target.dataset.productEdit);return;}
    if(target.dataset.productCopy){working=clone(data.draft);const p=clone(working.catalog.products.find(p=>p.id===target.dataset.productCopy));p.id=id('product');p.name.ru+=' — копия';p.status='draft';working.catalog.products.push(p);section='products';itemId=p.id;history.replaceState(null,'','#products/'+p.id);markDirty();render();return;}
    if(target.dataset.productTrash){if(!await confirmAction('Переместить товар в корзину?','После публикации товар исчезнет из витрины. Его можно восстановить в разделе «Корзина».','В корзину'))return;working.catalog.products.find(p=>p.id===target.dataset.productTrash).status='trash';await save('Товар перемещён в корзину');return;}
    if(target.dataset.galleryRemove){collect();const[p,i]=target.dataset.galleryRemove.split(':').map(Number);working.catalog.products[p].images.splice(i,1);markDirty();render();return;}
    if(target.dataset.galleryMove){collect();const[p,i,d]=target.dataset.galleryMove.split(':').map(Number),images=working.catalog.products[p].images,j=i+d;if(j>=0&&j<images.length)[images[i],images[j]]=[images[j],images[i]];markDirty();render();return;}
    if(target.dataset.productRestore){working.catalog.products.find(p=>p.id===target.dataset.productRestore).status='draft';await save('Товар восстановлен');return;}
    if(target.dataset.articleEdit){await navigate('articles/'+target.dataset.articleEdit);return;}if(target.dataset.documentEdit){await navigate('documents/'+target.dataset.documentEdit);return;}
    if(target.dataset.articleState){const a=working.content.articles.find(a=>a.id===target.dataset.articleState);a.status=a.status==='trash'?'draft':'trash';await save('Статус статьи');return;}
    if(target.dataset.add){addCollection(target.dataset.add);return;}
    if(target.dataset.remove){collect();const [key,index]=target.dataset.remove.split(':');const row=working.content[key][Number(index)];if(key==='slides'&&working.content.slides.length===1){notify('Оставьте хотя бы один слайд.',true);return;}if(key==='sections'&&row.type==='builtin')row.visible=false;else{if(key==='categories')for(const p of working.catalog.products)if(p.category===row.id)p.category='';working.content[key].splice(Number(index),1);}markDirty();render();return;}
    if(target.dataset.move){collect();const[key,n,d]=target.dataset.move.split(':'),i=Number(n),j=i+Number(d),rows=working.content[key];if(j>=0&&j<rows.length)[rows[i],rows[j]]=[rows[j],rows[i]];markDirty();render();return;}
    if(target.dataset.pick){openPicker(target.dataset.pick,target.dataset.kind,target.hasAttribute('data-append'));return;}
    if(target.dataset.clearMedia){const input=$(`[name="${target.dataset.clearMedia}"]`);if(input){input.value='';input.closest('.media-field')?.querySelector('img')?.setAttribute('src',asset('assets/ivory.webp'));markDirty();}return;}
    if(target.hasAttribute('data-close-media')){$('#media-dialog').close();return;}
    if(target.dataset.chooseMedia){const m=data.media.find(m=>m.id===target.dataset.chooseMedia);$('#media-dialog').close();if(pickerCallback){const callback=pickerCallback;pickerCallback=null;await callback(m);return;}const input=$(`[name="${pickerTarget}"]`,$('#editor'));if(input){input.value=pickerAppend?[input.value,m.url].filter(Boolean).join('\n'):m.url;const image=input.closest('.media-field')?.querySelector('img');if(image)image.src=asset(m.url);markDirty();if(pickerAppend){collect();render();}}return;}
    if(target.id==='media-trash-toggle'){mediaTrash=!mediaTrash;render();return;}
    if(target.dataset.mediaState){const m=data.media.find(m=>m.id===target.dataset.mediaState);await api('media-trash',{id:m.id,restore:m.trash});await refresh();render();notify(m.trash?'Файл восстановлен.':'Файл перемещён в корзину.');return;}
    if(target.dataset.removeBlock){collect();const[doc,n]=target.dataset.removeBlock.split(':').map(Number);working.documents.documents[doc].blocks.splice(n,1);markDirty();render();return;}
    if(target.dataset.addBlock){collect();const[n,type]=target.dataset.addBlock.split(':');working.documents.documents[Number(n)].blocks.push(type==='table'?{type,rows:[['','']]}:{type,text:'',...(type==='heading'?{id:id('section')}:{})});markDirty();render();return;}
    if(target.dataset.addTableRow){collect();const[d,b]=target.dataset.addTableRow.split(':').map(Number);working.documents.documents[d].blocks[b].rows.push(['','']);markDirty();render();return;}
    if(target.dataset.removeTableRow){collect();const[d,b,r]=target.dataset.removeTableRow.split(':').map(Number);working.documents.documents[d].blocks[b].rows.splice(r,1);markDirty();render();return;}
    if(target.hasAttribute('data-import-word')){const index=Number(target.dataset.importWord);openPicker(null,'word',false,async file=>{const result=await api('import-docx',{id:file.id});if(result.blocks.length<2)throw new Error('В файле недостаточно текста.');collect();working.documents.documents[index].blocks=result.blocks;working.documents.documents[index].title=result.blocks.slice(0,2).map(b=>b.text).join(' ');working.links.files[working.documents.documents[index].id]=file.url;markDirty();render();notify('Текст перенесён в форму. Проверьте его перед сохранением.');});return;}
    if(target.dataset.addMenu){collect();const parts=target.dataset.addMenu.split(':'),row={label:{ru:'Новая ссылка',en:''},href:'#catalog'};if(parts[0]==='header')working.content.menus.header.push(row);else working.content.menus.footer[Number(parts[1])].items.push(row);markDirty();render();return;}
    if(target.dataset.removeMenu){collect();const parts=target.dataset.removeMenu.split(':');if(parts[0]==='header')working.content.menus.header.splice(Number(parts[1]),1);else working.content.menus.footer[Number(parts[1])].items.splice(Number(parts[2]),1);markDirty();render();return;}
    if(target.hasAttribute('data-add-footer-group')){collect();working.content.menus.footer.push({title:{ru:'Новая группа',en:''},items:[]});markDirty();render();return;}
    if(target.hasAttribute('data-remove-footer-group')){collect();working.content.menus.footer.splice(Number(target.dataset.removeFooterGroup),1);markDirty();render();return;}
    if(target.dataset.restoreVersion){if(!await confirmAction('Восстановить версию?','Выбранная версия заменит черновик. Опубликованный сайт пока не изменится.','Восстановить'))return;await api('restore',{revision:data.revision,id:target.dataset.restoreVersion});await refresh();render();notify('Версия восстановлена в черновик.');return;}
    if(target.hasAttribute('data-import-backup')){$('#backup-file').click();return;}
  }catch(error){busy=false;updateTop();notify(error.message,true);}});
  document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{
    if(form.id==='auth-form'){const f=new FormData(form),setup=form.dataset.setup==='true';$('#auth-error').hidden=true;if(setup&&f.get('password')!==f.get('repeat'))throw new Error('Пароли не совпадают.');$('#auth-submit').disabled=true;await api(setup?'setup':'login',{login:f.get('login'),password:f.get('password'),...(setup?{name:f.get('name')||'Администратор',token:setupToken}:{})});setupToken='';form.reset();await start();return;}
    if(form.id==='editor'){if(form.reportValidity())await save(form.dataset.label);return;}
    if(form.id==='password-form'){const f=new FormData(form);if(f.get('newPassword')!==f.get('repeatPassword'))throw new Error('Новые пароли не совпадают.');await api('password',{currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')});form.reset();notify('Пароль изменён.');return;}
  }catch(error){if(form.id==='auth-form'){$('#auth-error').textContent=error.message;$('#auth-error').hidden=false;}else notify(error.message,true);}finally{$('#auth-submit').disabled=false;}});
  $('#workspace').addEventListener('input',event=>{if(event.target.closest('#editor'))markDirty();if(event.target.id==='product-search'){productSearch=event.target.value;$('#product-table').innerHTML=productTable();}if(event.target.id==='content-search'){collect();contentSearch=event.target.value;$('#content-fields').innerHTML=textFields();}if(event.target.id==='library-search'){mediaSearch=event.target.value;$('#library-grid').innerHTML=mediaCards(data.media.filter(m=>Boolean(m.trash)===mediaTrash&&(!mediaSearch||m.name.toLowerCase().includes(mediaSearch.toLowerCase()))));}});
  $('#workspace').addEventListener('change',async event=>{try{if(event.target.id==='product-status'){productStatus=event.target.value;$('#product-table').innerHTML=productTable();}if(event.target.id==='content-group'){collect();contentGroup=event.target.value;$('#content-fields').innerHTML=textFields();}if(event.target.id==='library-upload'){await uploadFiles([...event.target.files]);render();}if(event.target.closest('.doc-block')&&event.target.name?.endsWith('.type')){collect();const name=event.target.name.slice(0,-5);const block=getPath(working,name);if(block.type==='table'&&!block.rows)block.rows=[['','']];else if(block.type!=='table'&&block.text===undefined)block.text='';markDirty();render();}}catch(error){notify(error.message,true);}});
  $('#media-search').addEventListener('input',renderPicker);
  $('#media-picker-upload').addEventListener('change',async event=>{try{await uploadFiles([...event.target.files]);event.target.value='';renderPicker();}catch(error){notify(error.message,true);}});
  $('#backup-file').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;const backup=JSON.parse(await file.text());if(backup.format!=='zamelano-content-v1'||!backup.payload)throw new Error('Выберите резервную копию ZAMELANO.');if(!await confirmAction('Загрузить резервную копию?','Содержимое файла заменит черновик. Опубликованный сайт пока останется прежним.','Загрузить'))return;await api('save',{revision:data.revision,payload:backup.payload,label:'Импорт резервной копии'});await refresh();render();notify('Копия загружена в черновик.');}catch(error){notify(error.message,true);}finally{event.target.value='';}});
  window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
  window.addEventListener('hashchange',()=>{if(!data)return;if(dirty){history.replaceState(null,'','#'+section+(itemId?'/'+itemId:''));notify('Сначала сохраните правки или перейдите через меню.',true);return;}working=clone(data.draft);readRoute();renderNav();render();});
  window.addEventListener('resize',syncSidebar);document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('#sidebar').classList.remove('is-open');syncSidebar();}});syncSidebar();
  start();
})();
